def find_max(numbers):
    biggest = numbers[0]
    for n in numbers:
        if n > biggest:
            biggest = n
    return biggest

example.code:
import random

# Milestone 2+4: full game loop with attempt counting
secret = random.randint(1, 100)
attempts = 0

print("I picked a number from 1 to 100. Guess it!")
while True:
    raw = input("Your guess: ")
    try:
        guess = int(raw)
    except ValueError:
        print("Numbers only, please.")
        continue
    attempts += 1
    if guess < secret:
        print("Higher!")
    elif guess > secret:
        print("Lower!")
    else:
        print(f"Correct! You got it in {attempts} tries.")
        break

